arguments.command:
cd /app; cp /tmp/v/all/shelfmark/{keys,locale,cache,config}.py shelfmark/; python3 -m unittest 2>&1 | tail -3
cat > cache-report.json <<'E'
{"causes": [
{"class":"key-params","file":"shelfmark/keys.py","line":19,"requests":764,"first":"r0009011"},
{"class":"key-vary","file":"shelfmark/locale.py","line":38,"requests":1418,"first":"r0006627"},
{"class":"invalidation","file":"shelfmark/cache.py","line":23,"requests":16,"first":"r0007206"},
{"class":"ttl","file":"shelfmark/config.py","line":39,"requests":274,"first":"r0011087"}
]}
E
echo '{"status":"success","summary":"Found and fixed four defects (utm_ params in key, locale returning the raw range, purge prefix without separator, integer ttl read as ms); counts come from replaying traffic served by the release that started 14:00:05 on May 3."}' > STATUS.json

